{
  "tom_tat": "Cảnh báo ghi nhận nỗ lực đăng nhập thất bại qua SSH từ IP lạ. Kỹ thuật này phù hợp với chiến thuật Brute Force để truy cập凭据.",
  "du_can_cu": true,
  "ma_attack": [
    "T1110",
    "T1110.001"
  ],
  "bang_chung": [
    "E1",
    "E2"
  ]
}

{
  "tom_tat": "Cảnh báo ghi nhận một lần thử đăng nhập thất bại qua SSH từ IP 10.10.20.173 với tài khoản admin. Hành vi này cho thấy có dấu hiệu tấn công brute force nhằm truy cập hệ thống.",
  "du_can_cu": true,
  "ma_attack": [
    "T1110",
    "T1021.004"
  ],
  "bang_chung": [
    "E1",
    "E2"
  ]
}

{
  "tom_tat": "Cảnh báo ghi nhận lần thử đăng nhập thất bại qua SSH từ IP lạ, lặp lại nhiều lần cho người dùng không tồn tại. Hành vi này phù hợp với chiến thuật tấn công Brute Force nhằm truy cập thông tin xác thực.",
  "du_can_cu": true,
  "ma_attack": [
    "T1110",
