{
  "tom_tat": "Cảnh báo ghi nhận lệnh tạo tác vụ định kỳ (schtasks.exe) nhằm chạy file exe tại thư mục Public khi đăng nhập, đây là dấu hiệu điển hình của kỹ thuật duy trì hoạt động.",
  "du_can_cu": true,
  "ma_attack": [
    "T1053.005",
    "T1136.001"
  ],
  "bang_chung": [
    "E2"
  ]
}

{
  "tom_tat": "Cảnh báo ghi nhận việc một trình ký tự (.exe) được thêm vào mục Run của registry người dùng để tự động khởi chạy khi hệ thống khởi động. Hành vi này thường nhằm thiết lập tính năng tồn tại (persistence) trên máy chủ.",
  "du_can_cu": true,
  "ma_attack": [
    "T1547.001",
    "T1136.001"
  ],
  "bang_chung": [
    "E2"
